.button {
	appearance: none;
	border: none;
	display: inline-flex;
	justify-content: center;
	align-items: center;
	height: 40px;
	width: auto;
	outline: none;
	border-radius: 6px;
	padding: 0 16px;
	background-color: hsl(200 98% 39%);
	color: white;
	font-size: 16px;
	line-height: 0;
	transition: 250ms background-color;
}

.button:hover {
	background-color: hsl(201 96% 32%);
}

.button:focus-visible {
	outline: 2px solid hsl(200 98% 39%);
	outline-offset: 2px;
}

.button:active {
	background-color: hsl(201 90% 27%);
}

[data-theme*="dark"] .button {
	background-color: hsl(201 96% 32%);
	color: hsla(0 100% 100% / 0.9);
}

[data-theme*="dark"] .button:hover {
	background-color: hsl(200 98% 39%);
}

[data-theme*="dark"] .button:active {
	background-color: hsl(199 89% 48%);
}

import style from "./button.module.css";

import { Button } from "@kobalte/core/button";

export function BasicExample() {
	return <Button class={style.button}>Click me</Button>;
}

.dialog__trigger {
	appearance: none;
	border: none;
	display: inline-flex;
	justify-content: center;
	align-items: center;
	height: 40px;
	width: auto;
	outline: none;
	border-radius: 6px;
	padding: 0 16px;
	background-color: hsl(200 98% 39%);
	color: white;
	font-size: 16px;
	line-height: 0;
	transition: 250ms background-color;
}

.dialog__trigger:hover {
	background-color: hsl(201 96% 32%);
}

.dialog__trigger:focus-visible {
	outline: 2px solid hsl(200 98% 39%);
	outline-offset: 2px;
}

.dialog__trigger:active {
	background-color: hsl(201 90% 27%);
}

.dialog__overlay {
	position: fixed;
	inset: 0;
	z-index: 50;
	background-color: rgb(0 0 0 / 0.2);
	animation: overlayHide 250ms ease 100ms forwards;
}

.dialog__overlay[data-expanded] {
	animation: overlayShow 250ms ease;
}

.dialog__positioner {
	position: fixed;
	inset: 0;
	z-index: 50;
	display: flex;
	align-items: center;
	justify-content: center;
}

.dialog__content {
	z-index: 50;
	max-width: min(calc(100vw - 16px), 500px);
	border: 1px solid hsl(240 5% 84%);
	border-radius: 6px;
	padding: 16px;
	background-color: white;
	box-shadow:
		0 10px 15px -3px rgb(0 0 0 / 0.1),
		0 4px 6px -4px rgb(0 0 0 / 0.1);
	animation: contentHide 300ms ease-in forwards;
}

.dialog__content[data-expanded] {
	animation: contentShow 300ms ease-out;
}

.dialog__header {
	display: flex;
	align-items: baseline;
	justify-content: space-between;
	margin-bottom: 12px;
}

.dialog__close-button {
	height: 25px;
	width: 25px;
	color: hsl(240 5% 34%);
}

.dialog__title {
	font-size: 20px;
	font-weight: 500;
	color: hsl(240 6% 10%);
}

.dialog__description {
	font-size: 16px;
	color: hsl(240 5% 26%);
}

@keyframes overlayShow {
	from {
		opacity: 0;
	}
	to {
		opacity: 1;
	}
}

@keyframes overlayHide {
	from {
		opacity: 1;
	}
	to {
		opacity: 0;
	}
}

@keyframes contentShow {
	from {
		opacity: 0;
		transform: scale(0.96);
	}
	to {
		opacity: 1;
		transform: scale(1);
	}
}

@keyframes contentHide {
	from {
		opacity: 1;
		transform: scale(1);
	}
	to {
		opacity: 0;
		transform: scale(0.96);
	}
}

[data-theme*="dark"] .dialog__trigger {
	background-color: hsl(201 96% 32%);
	color: hsla(0 100% 100% / 0.9);
}

[data-theme*="dark"] .dialog__trigger:hover {
	background-color: hsl(200 98% 39%);
}

[data-theme*="dark"] .dialog__trigger:active {
	background-color: hsl(199 89% 48%);
}

[data-theme*="dark"] .dialog__content {
	border: 1px solid hsl(240 5% 26%);
	background-color: hsl(240 4% 16%);
	box-shadow: none;
}

[data-theme*="dark"] .dialog__close-button {
	color: hsl(0 100% 100% / 0.8);
}

[data-theme*="dark"] .dialog__title {
	color: hsl(0 100% 100% / 0.9);
}

[data-theme*="dark"] .dialog__description {
	color: hsl(0 100% 100% / 0.7);
}

.tabs {
	width: 100%;
}

.tabs[data-orientation="vertical"] {
	display: flex;
}

.tabs__list {
	position: relative;
	display: flex;
}

.tabs__list[data-orientation="horizontal"] {
	align-items: center;
	border-bottom: 1px solid hsl(240 5% 84%);
}

.tabs__list[data-orientation="vertical"] {
	flex-direction: column;
	align-items: stretch;
	border-right: 1px solid hsl(240 5% 84%);
}

.tabs__indicator {
	position: absolute;
	background-color: hsl(200 98% 39%);
	transition: all 250ms;
}

.tabs__indicator[data-orientation="horizontal"] {
	bottom: -1px;
	height: 2px;
}

.tabs__indicator[data-orientation="vertical"] {
	right: -1px;
	width: 2px;
}

.tabs__trigger {
	display: inline-block;
	border: none;
	background: none;
	padding: 8px 16px;
	outline: none;
}

.tabs__trigger:hover {
	background-color: hsl(0 0% 98%);
	color: hsl(240 5% 34%);
}

.tabs__trigger:focus-visible {
	background-color: hsl(240 5% 96%);
}

.tabs__trigger[data-disabled],
.tabs__trigger[data-disabled]:hover {
	opacity: 0.5;
	background-color: transparent;
}

.tabs__content {
	padding: 16px;
}

[data-theme*="dark"] .tabs__list {
	border-color: hsl(240 5% 26%);
}

[data-theme*="dark"] .tabs__trigger {
	color: rgb(255 255 255 / 0.9);
}

[data-theme*="dark"] .tabs__trigger:hover {
	background-color: hsl(240 4% 16%);
}

[data-theme*="dark"] .tabs__trigger:focus-visible {
	background-color: hsl(240 4% 16%);
}
